svg.script:
(function () {
  // CA annuel 300 000 € HT, charges variables = 40 % du CA (taux de MCV 60 %).
  var CA = 300000, TCV = 0.4, CF_QUESTION = 135000;
  var X0 = 70, X1 = 450, Y0 = 250, Y1 = 40;
  var KX = (X1 - X0) / CA, KY = (Y0 - Y1) / 300000;
  var MOIS = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"];
  var $ = function (id) { return document.getElementById(id); };
  var svg = document.documentElement;
  function px(v) { return X0 + v * KX; }
  function py(v) { return Y0 - v * KY; }
  function euros(v) { return Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " €"; }
  function f1(v) { return (Math.round(v * 10) / 10).toString().replace(".", ","); }

  var cfCourant = CF_QUESTION;
  function dessiner(CF) {
    var SR = CF / (1 - TCV);
    var yCF = py(CF), yCT = py(CF + TCV * CA);
    $("cf").setAttribute("d", "M" + X0 + " " + yCF + " L" + X1 + " " + yCF);
    $("ct").setAttribute("d", "M" + X0 + " " + yCF + " L" + X1 + " " + yCT);
    $("pc").setAttribute("cy", yCF); $("pt").setAttribute("y", yCF + 4.5); $("pzone").setAttribute("y", yCF - 20);
    var dedans = SR <= CA;
    var xs = px(Math.min(SR, CA)), ys = py(Math.min(SR, CA));
    if (dedans) {
      $("perte").setAttribute("d", "M" + X0 + " " + Y0 + " L" + X0 + " " + yCF + " L" + xs + " " + ys + " Z");
      $("benef").setAttribute("d", SR < CA ? "M" + xs + " " + ys + " L" + X1 + " " + py(CA) + " L" + X1 + " " + yCT + " Z" : "");
      $("srg").setAttribute("visibility", "visible");
      $("srl").setAttribute("x1", xs); $("srl").setAttribute("x2", xs); $("srl").setAttribute("y1", ys);
      $("srp").setAttribute("cx", xs); $("srp").setAttribute("cy", ys);
      $("srt").setAttribute("x", Math.min(xs, 436));
    } else {
      $("perte").setAttribute("d", "M" + X0 + " " + Y0 + " L" + X0 + " " + yCF + " L" + X1 + " " + yCT + " L" + X1 + " " + py(CA) + " Z");
      $("benef").setAttribute("d", "");
      $("srg").setAttribute("visibility", "hidden");
    }
    // étiquettes « perte » et « bénéfice » au milieu de leur zone
    var xp = X0 + 40, ycaP = py(xp - X0 > 0 ? (xp - X0) / KX : 0), yctP = py(CF + TCV * (xp - X0) / KX);
    $("tperte").setAttribute("x", xp); $("tperte").setAttribute("y", (ycaP + yctP) / 2 + 5);
    $("tperte").setAttribute("visibility", ycaP - yctP > 18 ? "visible" : "hidden");
    var xb = X1 - 35, vb = (xb - X0) / KX, ycaB = py(vb), yctB = py(CF + TCV * vb);
    $("tbenef").setAttribute("y", yctB + 18);
    $("tbenef").setAttribute("visibility", yctB - ycaB > 6 ? "visible" : "hidden");
    $("mesures").textContent = "CF = " + euros(CF) + "  ·  taux de MCV = 60 %  ·  SR = " + euros(SR);
    var m = SR / CA * 12;
    var t;
    if (m > 12.001) t = "Pas de point mort : perte de " + euros(CF - (1 - TCV) * CA);
    else if (Math.abs(m - Math.round(m)) < 0.05) t = "Point mort : fin " + MOIS[Math.round(m) - 1] + " (" + Math.round(m) + " mois)";
    else t = "Point mort : après " + f1(m) + " mois, en " + MOIS[Math.floor(m)];
    $("pm").textContent = t;
  }

  function finirAnimations() {
    ["cf", "ca", "ct"].forEach(function (id) { $(id).classList.remove("trace"); });
    Array.prototype.forEach.call(document.querySelectorAll(".anim"), function (el) { el.classList.remove("anim"); });
  }

  var poignee = $("poignee"), actif = false;
  function versSVG(e) {
    var p = svg.createSVGPoint(); p.x = e.clientX; p.y = e.clientY;
    return p.matrixTransform(svg.getScreenCTM().inverse());
  }
  poignee.addEventListener("pointerdown", function (e) {
    actif = true; finirAnimations(); $("aide").setAttribute("visibility", "hidden");
    poignee.setPointerCapture(e.pointerId); e.preventDefault();
  });
  poignee.addEventListener("pointermove", function (e) {
    if (!actif) return;
    var v = (Y0 - versSVG(e).y) / KY;
    cfCourant = Math.max(30000, Math.min(195000, Math.round(v / 1000) * 1000));
    dessiner(cfCourant);
  });
  function lacher() { if (actif) verifierDefi(); actif = false; }
  poignee.addEventListener("pointerup", lacher);
  poignee.addEventListener("pointercancel", lacher);

  $("rejouer").addEventListener("click", function () {
    cfCourant = CF_QUESTION; defi = -1; $("defi").setAttribute("visibility", "hidden");
    dessiner(CF_QUESTION);
    ["cf", "ca", "ct"].forEach(function (id) {
      var el = $(id); el.classList.remove("trace"); void el.getBoundingClientRect(); el.classList.add("trace");
    });
  });

  // Défis : CF exacts = SR × 60 %, tolérance de ± 4 000 € sur les charges fixes (large pour le doigt)
  var DEFIS = [
    { texte: "règle les CF pour un SR de 200 000 €", cible: 120000 },
    { texte: "règle les CF pour un point mort fin juin", cible: 90000 },
    { texte: "règle les CF pour un résultat tout juste nul", cible: 180000 }
  ];
  var defi = -1;
  function afficherDefi() {
    $("defi").setAttribute("visibility", "visible");
    $("defifond").setAttribute("stroke", "#d9b26f");
    $("defi1").textContent = "🎯 Défi " + (defi + 1) + "/" + DEFIS.length;
    $("defi2").textContent = DEFIS[defi].texte;
  }
  function verifierDefi() {
    if (defi < 0) return;
    if (Math.abs(cfCourant - DEFIS[defi].cible) > 4000) return;
    cfCourant = DEFIS[defi].cible; dessiner(cfCourant);
    $("defifond").setAttribute("stroke", "#5fd08a");
    $("defi1").textContent = "✓ Bravo ! CF = " + euros(cfCourant);
    var fini = defi === DEFIS.length - 1;
    $("defi2").textContent = fini ? "Tous les défis sont réussis 🎉" : "Défi suivant dans un instant…";
    var suivant = defi + 1; defi = fini ? -1 : -2;
    if (!fini) setTimeout(function () { defi = suivant; afficherDefi(); }, 1600);
  }
  $("bdefi").addEventListener("click", function () {
    finirAnimations(); $("aide").setAttribute("visibility", "visible");
    defi = 0; afficherDefi();
  });

  dessiner(CF_QUESTION);
})();
